header_type_specs.canonical_declaration:
typedef struct mqtt_tcp_callbacks {
    mqtt_tcp_on_accept_fn on_accept;
    mqtt_tcp_on_data_fn on_data;
    mqtt_tcp_on_close_fn on_close;
} mqtt_tcp_callbacks_t;

typedef struct mqtt_connect_payload {
    char* client_id;
    uint16_t keep_alive;
    bool clean_session;
} mqtt_connect_payload_t;

typedef struct mqtt_publish_payload {
    char* topic_name;
    uint8_t* payload;
    size_t payload_len;
    uint8_t qos;
    bool retain;
    bool dup;
    bool has_packet_id;
    uint16_t packet_id;
} mqtt_publish_payload_t;

typedef struct mqtt_subscribe_topic {
    char* filter;
    uint8_t qos;
} mqtt_subscribe_topic_t;

typedef struct mqtt_subscribe_payload {
    uint16_t packet_id;
    mqtt_subscribe_topic_t* topics;
    size_t topic_count;
} mqtt_subscribe_payload_t;

typedef struct mqtt_packet {
    mqtt_packet_type_t type;
    union {
        mqtt_connect_payload_t connect;
        mqtt_publish_payload_t publish;
        mqtt_subscribe_payload_t subscribe;
    } v;
} mqtt_packet_t;

typedef struct mqtt_bytes {
    uint8_t* data;
    size_t len;
} mqtt_bytes_t;
